import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def transcript(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    result = monitor_flag_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flag_values_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # another,comment", " a , 2 , 1 \n",
             " b , -1 , 0 ", " c , 3 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        transcript("a", 2, True), transcript("b", -1, False), transcript("c", 3, None)
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "valid,1,0", " \t", line])


def test_parse_transcript_log_empty():
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", "  ", " # comment"]) == []


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        transcript("a", 9, True),
        transcript("c", 2, True),
        transcript("b", 2, False),
        transcript("a", 1, None),
        transcript("c", 2, False),
    ]
    assert dedupe_transcripts(events) == [events[3], events[2], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_padded_and_range_filtered():
    events = [
        transcript("outside-before", 0, True),
        transcript("first", 1, True),
        transcript("last", 4, True),
        transcript("last-again", 4, True),
        transcript("false", 2, False),
        transcript("unknown", 3, None),
        transcript("outside-after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_flag_counts(events, 4, 4) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_monitor_summary_pooled_rounded_and_calendar_window(days, recent):
    groups = {
        "small": [transcript("a", 1, True)],
        "large": [
            transcript("b", 4, True), transcript("c", 5, False),
            transcript("d", 2, None), transcript("e", 2, False),
            transcript("f", 2, False),
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "winner": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["winner", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["winner", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3),
     ([1, 1, 0, 1, 1, 1, 0, 1], 3), ([1, -1, 2], 1)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
